import React from 'react';
import { Box, LinearProgress, Typography, Chip, Stack } from '@mui/material';
import type { OcrValidation } from './OCRValidationBanner';

interface OcrMetadata {
  strategy?: string;
  engines?: string[];
  thermalDetection?: { is_thermal?: boolean; receipt_type?: string };
  blurDetected?: boolean;
  processingTimeMs?: number;
  pageCount?: number;
}

interface InvoicePreviewProps {
  fileName?: string;
  ocrValidation?: OcrValidation | null;
  ocrMetadata?: OcrMetadata | null;
}

const qualityColor = (score: number): 'success' | 'warning' | 'error' => {
  if (score >= 0.7) return 'success';
  if (score >= 0.5) return 'warning';
  return 'error';
};

const InvoicePreview: React.FC<InvoicePreviewProps> = ({
  fileName,
  ocrValidation,
  ocrMetadata
}) => {
  const confidence = ocrValidation?.invoice_confidence ?? 0;
  const quality = ocrValidation?.ocr_quality_score ?? confidence;
  const pct = Math.round(confidence * 100);

  return (
    <Box sx={{ mb: 2 }}>
      {fileName && (
        <Typography variant="subtitle2" gutterBottom>
          {fileName}
        </Typography>
      )}
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
        <Typography variant="caption" color="text.secondary" sx={{ minWidth: 100 }}>
          Readability
        </Typography>
        <LinearProgress
          variant="determinate"
          value={Math.min(100, pct)}
          color={qualityColor(quality)}
          sx={{ flex: 1, height: 8, borderRadius: 1 }}
        />
        <Typography variant="caption">{pct}%</Typography>
      </Box>
      <Stack direction="row" spacing={0.5} flexWrap="wrap" useFlexGap>
        {ocrMetadata?.strategy && (
          <Chip label={`OCR: ${ocrMetadata.strategy}`} size="small" variant="outlined" />
        )}
        {ocrMetadata?.thermalDetection?.is_thermal && (
          <Chip
            label={`Thermal: ${ocrMetadata.thermalDetection.receipt_type || 'receipt'}`}
            size="small"
            color="info"
            variant="outlined"
          />
        )}
        {ocrMetadata?.blurDetected && (
          <Chip label="Blur detected" size="small" color="warning" variant="outlined" />
        )}
        {typeof ocrMetadata?.pageCount === 'number' && ocrMetadata.pageCount > 1 && (
          <Chip label={`${ocrMetadata.pageCount} pages`} size="small" variant="outlined" />
        )}
      </Stack>
    </Box>
  );
};

export default InvoicePreview;
