import React, { useEffect } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  CardMedia,
  Chip,
  Grid,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import {
  AccountBalance as FinanceIcon,
  ArrowForward as ArrowForwardIcon,
  GppGood as PatentIcon,
  Info as AboutIcon,
  Nature as EcoIcon,
  Factory as FactoryIcon,
  Insights as InsightsIcon,
  Login as LoginIcon,
  PersonAdd as RegisterIcon,
  Public as ClimateIcon,
  Savings as SavingsIcon,
  TrackChanges as MeasureIcon,
  CurrencyRupee as PricingIcon,
} from '@mui/icons-material';
import { Link as RouterLink, useLocation, useNavigate } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import { useRegistration } from '../context/RegistrationContext';
import BrandLockup from './BrandLockup';
import { BRAND_BODY_LOGO_SRC } from '../constants/brand';
import {
  ABOUT_US_SECTION,
  CLIMATE_AND_SAVINGS_HIGHLIGHTS,
  INDIA_SPECIFIC_INFO,
  PATENT_PENDING_HIGHLIGHT,
  PLATFORM_BENEFITS,
  POST_LOGIN_WORKFLOW,
  PRE_LOGIN_FOOTER_CTA,
  PRE_LOGIN_HERO,
  PRICING_TEASER_SECTION,
  PreLoginHighlight,
  WHY_MEASUREMENT_MATTERS,
} from '../constants/preLoginDashboardContent';
import { scrollToPageSection } from '../utils/scrollToPageSection';
import { preLoginHorizontalBannerImageSx } from '../constants/bannerIllustrationLayout';

const SECTION_ICONS = {
  why: MeasureIcon,
  climate: ClimateIcon,
  benefits: InsightsIcon,
  india: FactoryIcon,
} as const;

const imageCardSx = {
  borderRadius: 2,
  objectFit: 'cover' as const,
  aspectRatio: '16 / 10',
  bgcolor: 'action.hover',
};

interface HighlightSectionProps {
  id: string;
  title: string;
  items: PreLoginHighlight[];
  icon: React.ElementType;
}

const HighlightSection: React.FC<HighlightSectionProps> = ({ id, title, items, icon: SectionIcon }) => {
  const theme = useTheme();

  return (
    <Box id={id} component="section" sx={{ mb: { xs: 4, md: 5 } }}>
      <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 2.5 }}>
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            width: 40,
            height: 40,
            borderRadius: 2,
            bgcolor: alpha(theme.palette.primary.main, 0.12),
            color: 'primary.main',
          }}
        >
          <SectionIcon />
        </Box>
        <Typography variant="h5" component="h2" sx={{ fontWeight: 700 }}>
          {title}
        </Typography>
      </Stack>
      <Grid container spacing={2}>
        {items.map((item) => (
          <Grid item xs={12} sm={6} md={3} key={item.title}>
            <Card
              variant="outlined"
              sx={{
                height: '100%',
                borderColor: alpha(theme.palette.primary.main, 0.2),
                overflow: 'hidden',
                transition: 'border-color 0.2s, box-shadow 0.2s, transform 0.2s',
                '&:hover': {
                  borderColor: alpha(theme.palette.primary.main, 0.45),
                  boxShadow: theme.shadows[4],
                  transform: 'translateY(-2px)',
                },
              }}
            >
              <CardMedia
                component="img"
                image={item.image}
                alt={item.imageAlt}
                sx={imageCardSx}
              />
              <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
                  {item.title}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  {item.description}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Box>
  );
};

const PRE_LOGIN_ABOUT_US_SECTION_ID = 'about-us';

const PreLoginDashboard: React.FC = () => {
  const theme = useTheme();
  const location = useLocation();
  const navigate = useNavigate();
  const { isRegistered } = useRegistration();
  const isDark = theme.palette.mode === 'dark';

  useEffect(() => {
    if (isRegistered) {
      navigate('/dashboard', { replace: true });
    }
  }, [isRegistered, navigate]);

  useEffect(() => {
    if (location.hash === `#${PRE_LOGIN_ABOUT_US_SECTION_ID}`) {
      scrollToPageSection(PRE_LOGIN_ABOUT_US_SECTION_ID);
    }
  }, [location.hash]);

  if (isRegistered) {
    return null;
  }

  return (
    <Box sx={{ pb: 4 }}>
      <Paper
        elevation={0}
        sx={{
          p: { xs: 2, md: 3 },
          mb: 4,
          borderRadius: 3,
          overflow: 'hidden',
          border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.28 : 0.18)}`,
          background: isDark
            ? `linear-gradient(145deg, ${alpha(theme.palette.primary.dark, 0.22)} 0%, ${alpha(theme.palette.background.paper, 0.6)} 100%)`
            : 'linear-gradient(135deg, rgba(76, 175, 80, 0.08) 0%, rgba(46, 125, 50, 0.12) 100%)',
        }}
      >
        <Box sx={{ textAlign: 'center', mb: { xs: 2.5, md: 3 } }}>
          <BrandLockup variant="full" logoSrc={BRAND_BODY_LOGO_SRC} logoWidth="min(520px, 92vw)" />
          <Chip
            icon={<PatentIcon />}
            label={PATENT_PENDING_HIGHLIGHT.label}
            color="primary"
            sx={{
              mt: 2,
              fontWeight: 700,
              px: 0.5,
              border: `2px solid ${alpha(theme.palette.primary.main, 0.55)}`,
              bgcolor: alpha(theme.palette.primary.main, isDark ? 0.2 : 0.12),
              '& .MuiChip-label': { fontSize: '0.9rem' },
            }}
          />
        </Box>
        <Grid container spacing={3} alignItems="center">
          <Grid item xs={12} md={6} sx={{ order: { xs: 2, md: 1 } }}>
            <Chip
              label={PRE_LOGIN_HERO.chipLabel}
              size="small"
              color="primary"
              variant="outlined"
              sx={{ mb: 2 }}
            />
            <Typography
              variant="h3"
              component="h1"
              gutterBottom
              sx={{
                fontWeight: 800,
                fontSize: { xs: '1.75rem', md: '2.25rem' },
                background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
                backgroundClip: 'text',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
              }}
            >
              {PRE_LOGIN_HERO.title}
            </Typography>
            <Typography variant="h6" color="text.secondary" sx={{ mb: 2.5, fontWeight: 400, lineHeight: 1.5 }}>
              {PRE_LOGIN_HERO.subtitle}
            </Typography>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} flexWrap="wrap" useFlexGap>
              <Button
                component={RouterLink}
                to="/register?type=msme"
                variant="contained"
                size="large"
                startIcon={<RegisterIcon />}
                aria-label={PRE_LOGIN_HERO.registerAriaLabel}
                sx={{
                  py: 1.25,
                  background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
                  '&:hover': {
                    background: 'linear-gradient(135deg, #43a047 0%, #1b5e20 100%)',
                  },
                }}
              >
                Get started
              </Button>
              <Button
                component={RouterLink}
                to="/login?type=msme"
                variant="outlined"
                size="large"
                startIcon={<LoginIcon />}
                aria-label={PRE_LOGIN_HERO.loginAriaLabel}
                color="primary"
                sx={{ py: 1.25 }}
              >
                {PRE_LOGIN_HERO.loginLabel}
              </Button>
              <Button
                component={RouterLink}
                to="/pricing"
                variant="text"
                size="large"
                startIcon={<PricingIcon />}
                color="primary"
              >
                Pricing
              </Button>
            </Stack>
            <Stack
              direction="row"
              spacing={1}
              flexWrap="wrap"
              useFlexGap
              sx={{ mt: 2 }}
            >
              <Chip icon={<EcoIcon />} label="GHG scopes 1–3" size="small" variant="outlined" />
              <Chip icon={<SavingsIcon />} label="Carbon savings" size="small" variant="outlined" />
              <Chip icon={<FinanceIcon />} label="Green finance" size="small" variant="outlined" />
            </Stack>
          </Grid>
          <Grid item xs={12} md={6} sx={{ order: { xs: 1, md: 2 } }}>
            <Box
              component="img"
              src={PRE_LOGIN_HERO.image}
              alt={PRE_LOGIN_HERO.imageAlt}
              sx={{
                ...preLoginHorizontalBannerImageSx,
                borderRadius: 2,
                border: `1px solid ${alpha(theme.palette.divider, 0.6)}`,
                boxShadow: theme.shadows[6],
              }}
            />
          </Grid>
        </Grid>
      </Paper>

      <HighlightSection
        id="why-measure"
        title="Why carbon measurement matters"
        items={WHY_MEASUREMENT_MATTERS}
        icon={SECTION_ICONS.why}
      />

      <HighlightSection
        id="climate-savings"
        title="Climate impact & carbon savings"
        items={CLIMATE_AND_SAVINGS_HIGHLIGHTS}
        icon={SECTION_ICONS.climate}
      />

      <Box component="section" id="pricing" sx={{ mb: { xs: 4, md: 5 } }}>
        <Grid container spacing={3} alignItems="center">
          <Grid item xs={12} md={6}>
            <Box
              component="img"
              src={PRICING_TEASER_SECTION.image}
              alt={PRICING_TEASER_SECTION.imageAlt}
              sx={{
                ...preLoginHorizontalBannerImageSx,
                borderRadius: 2,
                border: `1px solid ${alpha(theme.palette.divider, 0.6)}`,
                boxShadow: theme.shadows[3],
              }}
            />
          </Grid>
          <Grid item xs={12} md={6}>
            <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 1.5 }}>
              <Box
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: 40,
                  height: 40,
                  borderRadius: 2,
                  bgcolor: alpha(theme.palette.primary.main, 0.12),
                  color: 'primary.main',
                }}
              >
                <PricingIcon />
              </Box>
              <Typography variant="h5" component="h2" sx={{ fontWeight: 700 }}>
                {PRICING_TEASER_SECTION.title}
              </Typography>
            </Stack>
            <Typography variant="body1" color="text.secondary" sx={{ mb: 2 }}>
              {PRICING_TEASER_SECTION.description}
            </Typography>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} flexWrap="wrap" useFlexGap>
              <Button
                component={RouterLink}
                to="/pricing"
                variant="contained"
                startIcon={<PricingIcon />}
                sx={{
                  background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
                  '&:hover': {
                    background: 'linear-gradient(135deg, #43a047 0%, #1b5e20 100%)',
                  },
                }}
              >
                {PRICING_TEASER_SECTION.ctaPricing}
              </Button>
              <Button
                component={RouterLink}
                to="/register?type=msme"
                variant="outlined"
                startIcon={<RegisterIcon />}
              >
                {PRICING_TEASER_SECTION.ctaRegister}
              </Button>
              <Button
                component={RouterLink}
                to="/login?type=msme"
                variant="text"
                startIcon={<LoginIcon />}
                color="primary"
              >
                {PRICING_TEASER_SECTION.ctaLogin}
              </Button>
            </Stack>
          </Grid>
        </Grid>
      </Box>

      <HighlightSection
        id="benefits"
        title="Platform benefits after sign-in"
        items={PLATFORM_BENEFITS}
        icon={SECTION_ICONS.benefits}
      />

      <HighlightSection
        id="india"
        title="India-specific context"
        items={INDIA_SPECIFIC_INFO}
        icon={SECTION_ICONS.india}
      />

      <Box component="section" id="about-us" sx={{ mb: { xs: 4, md: 5 } }}>
        <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 2 }}>
          <Box
            sx={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              width: 40,
              height: 40,
              borderRadius: 2,
              bgcolor: alpha(theme.palette.primary.main, 0.12),
              color: 'primary.main',
            }}
          >
            <AboutIcon />
          </Box>
          <Typography variant="h5" component="h2" sx={{ fontWeight: 700 }}>
            {ABOUT_US_SECTION.title}
          </Typography>
        </Stack>
        <Paper
          elevation={0}
          sx={{
            p: { xs: 2, md: 3 },
            borderRadius: 3,
            border: `2px solid ${alpha(theme.palette.primary.main, isDark ? 0.45 : 0.35)}`,
            bgcolor: alpha(theme.palette.primary.main, isDark ? 0.1 : 0.06),
          }}
        >
          <Stack direction="row" spacing={1.5} alignItems="flex-start" sx={{ mb: 2 }}>
            <PatentIcon color="primary" sx={{ mt: 0.25 }} />
            <Box>
              <Typography variant="subtitle1" sx={{ fontWeight: 800, color: 'primary.main', mb: 0.5 }}>
                {PATENT_PENDING_HIGHLIGHT.label}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {PATENT_PENDING_HIGHLIGHT.description}
              </Typography>
            </Box>
          </Stack>
          <Typography variant="body1" sx={{ fontWeight: 600, mb: 1.5 }}>
            {ABOUT_US_SECTION.lead}
          </Typography>
          {ABOUT_US_SECTION.paragraphs.map((paragraph) => (
            <Typography key={paragraph.slice(0, 48)} variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
              {paragraph}
            </Typography>
          ))}
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Questions or partnerships? Reach us at{' '}
            <Box
              component="a"
              href={`mailto:${ABOUT_US_SECTION.contactEmail}`}
              sx={{ color: 'primary.main', fontWeight: 600, textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}
            >
              {ABOUT_US_SECTION.contactEmail}
            </Box>
            .
          </Typography>
          <Button component={RouterLink} to="/about-us" variant="outlined" endIcon={<ArrowForwardIcon />}>
            Read full About us
          </Button>
        </Paper>
      </Box>

      <Box component="section" id="workflow" sx={{ mb: 4 }}>
        <Typography variant="h5" component="h2" sx={{ fontWeight: 700, mb: 2.5 }}>
          Your workflow after login
        </Typography>
        <Grid container spacing={2}>
          {POST_LOGIN_WORKFLOW.map((step) => (
            <Grid item xs={12} sm={6} md={3} key={step.step}>
              <Paper
                sx={{
                  height: '100%',
                  overflow: 'hidden',
                  border: `1px solid ${alpha(theme.palette.divider, 0.8)}`,
                }}
              >
                <Box sx={{ position: 'relative' }}>
                  <Box
                    component="img"
                    src={step.image}
                    alt={step.imageAlt}
                    sx={{ width: '100%', display: 'block', ...imageCardSx, borderRadius: 0 }}
                  />
                  <Chip
                    label={`Step ${step.step}`}
                    size="small"
                    color="primary"
                    sx={{
                      position: 'absolute',
                      top: 12,
                      left: 12,
                      fontWeight: 700,
                    }}
                  />
                </Box>
                <Box sx={{ p: 2 }}>
                  <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
                    {step.title}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    {step.description}
                  </Typography>
                </Box>
              </Paper>
            </Grid>
          ))}
        </Grid>
      </Box>

      <Paper
        elevation={0}
        sx={{
          p: { xs: 2, md: 3 },
          borderRadius: 3,
          overflow: 'hidden',
          border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.28 : 0.18)}`,
          bgcolor: alpha(theme.palette.primary.main, isDark ? 0.08 : 0.04),
        }}
      >
        <Grid container spacing={3} alignItems="center">
          <Grid item xs={12} md={5}>
            <Box
              component="img"
              src={PRE_LOGIN_HERO.image}
              alt="Preview of emissions dashboard after sign-in"
              sx={{
                ...preLoginHorizontalBannerImageSx,
                borderRadius: 2,
                border: `1px solid ${alpha(theme.palette.divider, 0.5)}`,
              }}
            />
          </Grid>
          <Grid item xs={12} md={7} sx={{ textAlign: { xs: 'center', md: 'left' } }}>
            <Typography variant="h6" sx={{ fontWeight: 700, mb: 1 }}>
              {PRE_LOGIN_FOOTER_CTA.title}
            </Typography>
            <Stack
              direction={{ xs: 'column', sm: 'row' }}
              spacing={1.5}
              justifyContent={{ xs: 'center', md: 'flex-start' }}
              flexWrap="wrap"
              useFlexGap
              sx={{ mt: 2 }}
            >
              <Button
                component={RouterLink}
                to="/register?type=msme"
                variant="contained"
                size="large"
                endIcon={<ArrowForwardIcon />}
                sx={{
                  background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
                  '&:hover': {
                    background: 'linear-gradient(135deg, #43a047 0%, #1b5e20 100%)',
                  },
                }}
              >
                {PRE_LOGIN_FOOTER_CTA.registerLabel}
              </Button>
              <Button
                component={RouterLink}
                to="/login?type=msme"
                variant="outlined"
                size="large"
                startIcon={<LoginIcon />}
                color="primary"
              >
                {PRE_LOGIN_FOOTER_CTA.loginLabel}
              </Button>
            </Stack>
          </Grid>
        </Grid>
      </Paper>
    </Box>
  );
};

export default PreLoginDashboard;
