const EMISSION_SOURCE_BUCKETS = [
  'Fuel',
  'Transportation',
  'Electricity',
  'Water',
  'Chemicals',
  'Materials',
  'Manufacturing',
  'Waste',
  'Other',
] as const;

type EmissionSourceBucket = (typeof EMISSION_SOURCE_BUCKETS)[number];

function mapLabelToEmissionSourceBucket(raw: string): EmissionSourceBucket {
  const s = raw.toLowerCase().replace(/_/g, ' ');
  if (/\b(fuel|diesel|petrol|gasoline|lpg|cng|lng|furnace oil|hfo|combustion)\b/.test(s)) return 'Fuel';
  if (/\b(transport|vehicle|fleet|logistics|freight|delivery|shipping|commute|travel|mobility)\b/.test(s)) {
    return 'Transportation';
  }
  if (/\b(electric|grid|power|utility|kwh|mwh|energy bill|scope\s*2)\b/.test(s)) return 'Electricity';
  if (/water|wastewater|effluent|sewage/.test(s)) return 'Water';
  if (/chemical|solvent|paint|acid|alkali|adhesive|reagent|hazardous/.test(s)) return 'Chemicals';
  if (/raw material|materials|procurement|supplier|purchase|inventory|inputs|packaging/.test(s)) return 'Materials';
  if (/manufactur|process line|machinery|production|fabrication/.test(s)) return 'Manufacturing';
  if (/waste|landfill|incineration|scrap|recycl/.test(s)) return 'Waste';
  return 'Other';
}

function aggregateEmissionSourcesFromKgRows(rows: { label: string; kg: number }[]) {
  const acc = new Map<EmissionSourceBucket, number>();
  EMISSION_SOURCE_BUCKETS.forEach((b) => acc.set(b, 0));
  rows.forEach(({ label, kg }) => {
    const b = mapLabelToEmissionSourceBucket(label);
    acc.set(b, (acc.get(b) || 0) + Math.max(0, kg));
  });
  return EMISSION_SOURCE_BUCKETS.map((name) => ({
    name,
    kg: acc.get(name) || 0,
    tCO2e: (acc.get(name) || 0) / 1000,
  })).filter((r) => r.kg > 0);
}

function flattenEsgBreakdownToRows(esg: CarbonStatsPayload['esgScopes']): { label: string; kg: number }[] {
  if (!esg) return [];
  const rows: { label: string; kg: number }[] = [];
  const push = (scopeTag: string, breakdown: Record<string, number> | undefined) => {
    if (!breakdown || typeof breakdown !== 'object') return;
    Object.entries(breakdown).forEach(([key, val]) => {
      const kg = typeof val === 'number' && !Number.isNaN(val) ? val : 0;
      if (kg > 0) rows.push({ label: `${scopeTag} ${key.replace(/_/g, ' ')}`, kg });
    });
  };
  push('Scope 1', esg.scope1?.breakdown as Record<string, number> | undefined);
  push('Scope 2', esg.scope2?.breakdown as Record<string, number> | undefined);
  push('Scope 3', esg.scope3?.breakdown as Record<string, number> | undefined);
  return rows;
}

interface MSMEData {
  companyName: string;
  gstNumber: string;
}

/** Minimal profile fields for dashboard welcome and onboarding checks. */
function normalizeMsmeProfileForDashboard(raw: Record<string, unknown> | null | undefined): MSMEData | null {
  if (!raw || typeof raw !== 'object') return null;

  return {
    companyName: String(raw.companyName ?? ''),
    gstNumber: String(raw.gstNumber ?? ''),
  };
}

interface Achievement {
  title: string;
  description: string;
  level: string;
}

interface Milestone {
  title: string;
  description: string;
  currentValue: number;
  targetValue: number;
}

interface CarbonSavings {
  totalSavings: number;
  periodSavings: number;
  savingsPercentage: number;
  benchmarkComparison: {
    performance?: string;
  };
  achievements: Achievement[];
  nextMilestones: Milestone[];
}

interface AdditionalSavingsMetrics {
  totalCO2Saved?: number;
  costSavings?: number;
  environmentalImpact?: {
    treesEquivalent?: number;
    carsOffRoad?: number;
    energySaved?: number;
  };
}

interface DocumentCarbonSummary {
  periodType?: 'annual' | 'monthly' | 'weekly' | 'date-wise';
  startDate?: string;
  endDate?: string;
  totals?: {
    transactionCount?: number;
    totalAmount?: number;
    totalCO2Emissions?: number;
    averageEmissionPerTransaction?: number;
  };
}

function parseDocumentPeriodType(value: unknown): DocumentCarbonSummary['periodType'] {
  if (value === 'annual' || value === 'monthly' || value === 'weekly' || value === 'date-wise') {
    return value;
  }
  return undefined;
}

function parseOptionalNumber(value: unknown): number | undefined {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

interface CarbonStatsPayload {
  totalCO2Emissions?: number;
  esgScopes?: {
    scope1?: { total?: number; percentage?: number; breakdown?: Record<string, number> };
    scope2?: { total?: number; percentage?: number; breakdown?: Record<string, number> };
    scope3?: { total?: number; percentage?: number; breakdown?: Record<string, number> };
  };
  assessmentPeriod?: { startDate?: string; endDate?: string };
  lastAssessment?: string;
  predictions?: Array<{ predictedCO2?: number }>;
  categoryBreakdown?: Record<string, { co2Emissions?: number; co2?: number }>;
}

function unwrapApiPayload<T>(response: unknown): T | null {
  if (!response || typeof response !== 'object') {
    return null;
  }
  const record = response as Record<string, unknown>;
  const nestedData = record.data;
  if (nestedData && typeof nestedData === 'object') {
    return nestedData as T;
  }
  return record as T;
}

function getHotspotCopy(carbon: CarbonStatsPayload | undefined): string {
  const cat = carbon?.categoryBreakdown;
  if (cat && typeof cat === 'object') {
    const entries = Object.entries(cat)
      .map(([name, v]) => ({
        name,
        co2: Number((v as { co2Emissions?: number; co2?: number })?.co2Emissions ?? (v as { co2?: number })?.co2 ?? 0) || 0,
      }))
      .filter((e) => e.co2 > 0)
      .sort((a, b) => b.co2 - a.co2);
    if (entries.length > 0) {
      const labels = entries.slice(0, 3).map((e) => e.name.replace(/_/g, ' '));
      return `Highest-impact categories in this assessment: ${labels.join(', ')}.`;
    }
  }
  const esg = carbon?.esgScopes;
  if (!esg) return 'Complete a carbon assessment to see category hotspots.';
  const parts: { label: string; value: number }[] = [];
  const addBreak = (obj: Record<string, number> | undefined, prefix: string) => {
    if (!obj || typeof obj !== 'object') return;
    Object.entries(obj).forEach(([key, val]) => {
      if (typeof val === 'number' && val > 0) {
        const words = key.replace(/([A-Z])/g, ' $1').trim();
        parts.push({ label: `${prefix} — ${words}`, value: val });
      }
    });
  };
  addBreak(esg.scope1?.breakdown as Record<string, number> | undefined, 'Scope 1');
  addBreak(esg.scope2?.breakdown as Record<string, number> | undefined, 'Scope 2');
  addBreak(esg.scope3?.breakdown as Record<string, number> | undefined, 'Scope 3');
  if (parts.length === 0) {
    return 'Assessment data will highlight your highest-impact categories here.';
  }
  parts.sort((a, b) => b.value - a.value);
  const top = parts.slice(0, 3).map((p) => p.label);
  return `${top.join('; ')} — among the largest contributors in this assessment.`;
}

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const mutedInsetSurfaceSx = {
    bgcolor: isDark ? alpha(theme.palette.common.white, 0.05) : theme.palette.grey[50],
  };
  const [isLoading, setIsLoading] = useState(true);
  const [msmeData, setMsmeData] = useState<MSMEData | null>(null);
  const [statsData, setStatsData] = useState<any>(null);
  const [carbonSavings, setCarbonSavings] = useState<CarbonSavings | null>(null);
  const [additionalSavingsMetrics, setAdditionalSavingsMetrics] = useState<AdditionalSavingsMetrics | null>(null);
  const [documentCarbonSummary, setDocumentCarbonSummary] = useState<DocumentCarbonSummary | null>(null);
  const [msmeAdvisory, setMsmeAdvisory] = useState<MsmeAdvisoryPayload | null>(null);
  const [advisoryLoading, setAdvisoryLoading] = useState(true);
  const [advisoryError, setAdvisoryError] = useState<string | null>(null);
  const [guidanceDismissed, setGuidanceDismissed] = useState(() => {
    if (typeof window === 'undefined') {
      return false;
    }
    return window.localStorage.getItem('ci-platform-guidance-dismissed') === '1';
  });

  const carbonApi = statsData?.carbon as CarbonStatsPayload | undefined;
  const carbonScore = Number(statsData?.carbon?.currentScore || 0);
  const carbonEmissionsKg = Number(statsData?.carbon?.totalCO2Emissions || 0);
  const esg = carbonApi?.esgScopes;
  const s1Kg = Number(esg?.scope1?.total) || 0;
  const s2Kg = Number(esg?.scope2?.total) || 0;
  const s3Kg = Number(esg?.scope3?.total) || 0;
  const scopeSumKg = s1Kg + s2Kg + s3Kg;
  const predictions = carbonApi?.predictions;
  const forecastKgFromModel =
    predictions && predictions.length > 0
      ? predictions.reduce((sum, p) => sum + (Number(p.predictedCO2) || 0), 0)
      : null;
  const forecastTCO2e =
    forecastKgFromModel != null && forecastKgFromModel > 0
      ? forecastKgFromModel / 1000
      : carbonEmissionsKg > 0
        ? (carbonEmissionsKg * 1.08) / 1000
        : 0;
  const forecastCaption =
    forecastKgFromModel != null && forecastKgFromModel > 0
      ? 'Sum of modelled periods from your latest assessment'
      : carbonEmissionsKg > 0
        ? 'Estimated from current assessment footprint (+8% run-rate)'
        : 'Complete an assessment to see a forecast';
  const hotspotDescription = getHotspotCopy(carbonApi);
  const dashboardTopRecommendations = useMemo(() => {
    const candidates = [
      ...(msmeAdvisory?.outputs?.goalAdvisory?.prioritizedActions || []),
      ...(Array.isArray(statsData?.carbon?.recommendations) ? statsData.carbon.recommendations : []),
      ...(Array.isArray(statsData?.topRecommendations) ? statsData.topRecommendations : []),
    ];
    return candidates.filter(Boolean);
  }, [msmeAdvisory, statsData]);
  const lastAssessmentLabel = carbonApi?.lastAssessment
    ? new Date(carbonApi.lastAssessment).toLocaleString()
    : null;
  const assessmentPeriodLabel =
    carbonApi?.assessmentPeriod?.startDate && carbonApi?.assessmentPeriod?.endDate
      ? `${new Date(carbonApi.assessmentPeriod.startDate).toLocaleDateString()} – ${new Date(
          carbonApi.assessmentPeriod.endDate
        ).toLocaleDateString()}`
      : null;

  const getCarbonScoreColor = (score: number): string => {
    if (score >= 80) return 'success';
    if (score >= 50) return 'warning';
    return 'error';
  };

  const getCarbonScoreLabel = (score: number): string => {
    if (score >= 80) return 'Excellent';
    if (score >= 60) return 'Good';
    if (score >= 40) return 'Average';
    return 'Needs Improvement';
  };

  const getPerformanceLabel = (performance?: string): string => {
    return performance || 'Not Assessed';
  };

  const isLoadingSavings = false;

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [profileResponse, statsResponse, savingsResponse] = await Promise.all([
          ApiService.getMSMEProfile(),
          ApiService.getMSMEStats().catch(() => null),
          ApiService.getCarbonSavings({ period: 'monthly', includeTrends: false }).catch(() => null),
        ]);

        const profilePayload = unwrapApiPayload<Record<string, unknown>>(profileResponse);
        const statsPayload = unwrapApiPayload<Record<string, unknown>>(statsResponse);
        const savingsPayload = unwrapApiPayload<Record<string, unknown>>(savingsResponse);

        setMsmeData(normalizeMsmeProfileForDashboard(profilePayload));
        setStatsData(statsPayload || null);
        setCarbonSavings((savingsPayload?.savings as CarbonSavings) || null);
        setAdditionalSavingsMetrics((savingsPayload?.additionalMetrics as AdditionalSavingsMetrics) || null);

        const bulk = statsPayload?.documentBulkUpload as Record<string, unknown> | undefined;
        if (bulk) {
          const txCount = Number(bulk.totalTransactions) || 0;
          const co2 = Number(bulk.totalCO2Emissions) || 0;
          setDocumentCarbonSummary({
            periodType: parseDocumentPeriodType(bulk.periodType),
            totals: {
              transactionCount: txCount,
              totalAmount: parseOptionalNumber(bulk.totalAmount),
              totalCO2Emissions: co2,
              averageEmissionPerTransaction: txCount > 0 ? co2 / txCount : 0,
            },
          });
        } else {
          setDocumentCarbonSummary(null);
        }
      } catch (error) {
        console.error('Error fetching dashboard data:', error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  useEffect(() => {
    let cancelled = false;
    const loadAdvisory = async () => {
      setAdvisoryLoading(true);
      setAdvisoryError(null);
      try {
        const res = await ApiService.runMsmeAdvisory({
          signupGoal: getStoredSignupGoal() || 'baseline_footprint',
          period: 'annual',
        });
        if (!cancelled) {
          setMsmeAdvisory(unwrapApiPayload<MsmeAdvisoryPayload>(res));
        }
      } catch (e) {
        if (!cancelled) {
          setMsmeAdvisory(null);
          setAdvisoryError(e instanceof Error ? e.message : 'AI advisory unavailable');
        }
      } finally {
        if (!cancelled) {
          setAdvisoryLoading(false);
        }
      }
    };
    loadAdvisory();
    return () => {
      cancelled = true;
    };
  }, []);

  const emissionSourceBarData = useMemo(() => {
    const carbon = statsData?.carbon as CarbonStatsPayload | undefined;
    const cat = carbon?.categoryBreakdown;
    if (cat && typeof cat === 'object' && Object.keys(cat).length > 0) {
      const rows = Object.entries(cat).map(([name, v]) => {
        const raw = (v as { co2Emissions?: number; co2?: number })?.co2Emissions ?? (v as { co2?: number })?.co2 ?? 0;
        const kg = Number(raw) || 0;
        return { label: name.replace(/_/g, ' '), kg };
      });
      const aggregated = aggregateEmissionSourcesFromKgRows(rows);
      if (aggregated.length > 0) return aggregated;
    }
    return aggregateEmissionSourcesFromKgRows(flattenEsgBreakdownToRows(carbon?.esgScopes));
  }, [statsData]);

  const scopeSplitBarData = useMemo(() => {
    if (scopeSumKg <= 0) return [];
    const rows = [
      { name: `${GHG_SCOPE_COLORS.scope1.label} — direct`, kg: s1Kg, fill: GHG_SCOPE_HEX.scope1 },
      { name: `${GHG_SCOPE_COLORS.scope2.label} — energy`, kg: s2Kg, fill: GHG_SCOPE_HEX.scope2 },
      { name: `${GHG_SCOPE_COLORS.scope3.label} — value chain`, kg: s3Kg, fill: GHG_SCOPE_HEX.scope3 },
    ].filter((r) => r.kg > 0);
    return rows.map((r) => ({ ...r, tCO2e: r.kg / 1000 }));
  }, [s1Kg, s2Kg, s3Kg, scopeSumKg]);

  if (isLoading) {
    return (
      <Box
        sx={{
          py: { xs: 6, md: 8 },
          px: 2,
          maxWidth: 520,
          mx: 'auto',
          textAlign: 'center',
        }}
      >
        <CircularProgress size={44} thickness={4} sx={{ mb: 2.5, color: 'primary.main' }} />
        <Typography variant="h6" sx={{ fontWeight: 700, mb: 0.75, letterSpacing: '-0.02em' }}>
          Preparing your workspace
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3, lineHeight: 1.6 }}>
          Pulling your company profile, transactions, and emissions signals into one view.
        </Typography>
        <LinearProgress sx={{ height: 6, borderRadius: 3, maxWidth: 400, mx: 'auto' }} />
      </Box>
    );
  }

  if (!msmeData) {
    return (
      <Alert severity="info" sx={{ mt: 2 }}>
        No MSME registration found. Please complete the registration first.
        <Button variant="contained" sx={{ ml: 2 }} onClick={() => navigate('/msme-registration')}>
          Register Now
        </Button>
      </Alert>
    );
  }

  const scoreColor = getCarbonScoreColor(carbonScore) as 'success' | 'warning' | 'error';

  const totalCo2SavedKg = Number(
    additionalSavingsMetrics?.totalCO2Saved ?? carbonSavings?.totalSavings ?? 0
  );
  const periodCo2SavedKg = Number(carbonSavings?.periodSavings ?? 0);
  const savingsPercentage = Number(carbonSavings?.savingsPercentage ?? 0);
  const costSavingsInr = Number(
    additionalSavingsMetrics?.costSavings ?? totalCo2SavedKg * 0.05
  );
  const treesEquivalent = Number(
    additionalSavingsMetrics?.environmentalImpact?.treesEquivalent ??
      (totalCo2SavedKg > 0 ? Math.round(totalCo2SavedKg / 22) : 0)
  );
  const greenCreditsAvailable = Number(statsData?.carbonCredits?.availableCredits ?? 0);

  const transactionCount = Number(statsData?.transactions?.total ?? 0);
  const documentCount = Number(statsData?.documentBulkUpload?.totalDocuments ?? 0);
  const hasAssessment = carbonEmissionsKg > 0 || carbonScore > 0;
  const hasProfile = Boolean(msmeData?.companyName && msmeData?.gstNumber);
  const hasDocuments =
    documentCount > 0 ||
    Boolean(documentCarbonSummary?.totals) ||
    Number(statsData?.documentBulkUpload?.totalTransactions ?? 0) > 0;
  const hasTargets = typeof window !== 'undefined' && Boolean(
    window.localStorage.getItem('sustainow_emissions_reduction_target_pct_v1')
  );

  const dataQuality = computeDataQualityScore({
    hasProfile,
    hasAssessment,
    carbonEmissionsKg,
    transactionCount,
    documentCount,
    hasScopeBreakdown: scopeSumKg > 0,
  });

  const onboardingProgress = deriveOnboardingSteps({
    hasProfile,
    hasDocuments,
    hasAssessment,
    hasTargets,
  });

  const nextBestAction = deriveNextBestActionFromAdvisory(
    deriveNextBestAction({
      hasProfile,
      hasDocuments,
      hasAssessment,
      carbonScore,
      topRecommendationTitle: dashboardTopRecommendations[0]?.title,
      topRecommendationKg: Number(dashboardTopRecommendations[0]?.potentialCO2Reduction || 0),
    }),
    msmeAdvisory?.outputs?.goalAdvisory?.prioritizedActions?.[0] || msmeAdvisory?.nextBestAction
  );

  const frameworkGaps = deriveFrameworkDataGaps({
    hasProfile,
    hasAssessment,
    carbonEmissionsKg,
    transactionCount,
    documentCount,
    hasScopeBreakdown: scopeSumKg > 0,
  });

  const dismissGuidance = () => {
    setGuidanceDismissed(true);
    if (typeof window !== 'undefined') {
      window.localStorage.setItem('ci-platform-guidance-dismissed', '1');
    }
  };

  return (
    <Box>
      {!guidanceDismissed ? <PlatformGuidanceBanner variant="web" onDismiss={dismissGuidance} /> : null}

      <Box sx={{ mb: 3 }}>
        <Typography variant="h5" sx={{ fontWeight: 800, letterSpacing: '-0.02em', mb: 0.5 }}>
          Welcome back, {msmeData.companyName}
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 720, lineHeight: 1.6 }}>
          Your operational control center — emissions performance, charts, and shortcuts to assessment, documents, and
          reporting.
        </Typography>
      </Box>

      <DashboardMetricsGrid
        carbonScore={carbonScore}
        scoreLabel={getCarbonScoreLabel(carbonScore)}
        scoreColor={scoreColor}
        carbonEmissionsKg={carbonEmissionsKg}
        totalCo2SavedKg={totalCo2SavedKg}
        periodCo2SavedKg={periodCo2SavedKg}
        savingsPercentage={savingsPercentage}
        costSavingsInr={costSavingsInr}
        treesEquivalent={treesEquivalent}
        greenCreditsAvailable={greenCreditsAvailable}
        forecastTCO2e={forecastTCO2e}
      />

      <DashboardOnboardingChecklist progress={onboardingProgress} />
      <DashboardIsoReadinessCard />
      <DashboardMsmeAdvisoryPanel
        advisory={msmeAdvisory}
        loading={advisoryLoading}
        error={advisoryError}
      />
      <DashboardNextBestAction action={nextBestAction} />

      {frameworkGaps.length > 0 && dataQuality.level !== 'high' ? (
        <Paper variant="outlined" sx={{ p: 2, mb: 3, ...mutedInsetSurfaceSx }}>
          <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
            Disclosure readiness gaps
          </Typography>
          {frameworkGaps.map((gap) => (
            <Box
              key={`${gap.framework}-${gap.actionPath}`}
              sx={{
                display: 'flex',
                flexWrap: 'wrap',
                alignItems: 'center',
                justifyContent: 'space-between',
                gap: 1,
                py: 1,
                borderBottom: 1,
                borderColor: 'divider',
                '&:last-child': { borderBottom: 0 },
              }}
            >
              <Box sx={{ flex: 1, minWidth: 200 }}>
                <Typography variant="caption" color="primary" sx={{ fontWeight: 700 }}>
                  {gap.framework}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  {gap.gap}
                </Typography>
              </Box>
              <Button size="small" variant="outlined" onClick={() => navigate(gap.actionPath)}>
                {gap.actionLabel}
              </Button>
            </Box>
          ))}
        </Paper>
      ) : null}

      <Grid container spacing={4}>
        <Grid item xs={12}>
          <DashboardSectionHeading
            title="Performance"
            subtitle="Carbon score, footprint, and scope mix from your latest saved assessment."
          />
          <DashboardHero
            carbonScore={carbonScore}
            scoreLabel={getCarbonScoreLabel(carbonScore)}
            scoreColor={scoreColor}
            carbonEmissionsKg={carbonEmissionsKg}
            s1Kg={s1Kg}
            s2Kg={s2Kg}
            s3Kg={s3Kg}
            scopeSumKg={scopeSumKg}
            lastAssessmentLabel={lastAssessmentLabel}
            assessmentPeriodLabel={assessmentPeriodLabel}
            forecastTCO2e={forecastTCO2e}
            forecastCaption={forecastCaption}
            hotspotDescription={hotspotDescription}
            dataQuality={{
              level: dataQuality.level,
              label: dataQuality.label,
              score: dataQuality.score,
              hints: dataQuality.hints,
            }}
          />
        </Grid>

        <Grid item xs={12}>
          <DashboardQuickActions />
        </Grid>

        <Grid item xs={12}>
          <DashboardEmissionsCharts
            emissionSourceBarData={emissionSourceBarData}
            scopeSplitBarData={scopeSplitBarData}
            mutedInsetSurfaceSx={mutedInsetSurfaceSx}
          />
        </Grid>

        {documentCarbonSummary?.totals && (
          <Grid item xs={12}>
            <Alert
              severity="info"
              action={(
                <Button color="inherit" size="small" onClick={() => navigate('/data?tab=4')}>
                  View statistics
                </Button>
              )}
            >
              Bulk document processing: {documentCarbonSummary.totals.transactionCount || 0} transactions,{' '}
              {Number(documentCarbonSummary.totals.totalCO2Emissions || 0).toFixed(2)} kg CO₂e (
              {documentCarbonSummary.periodType || 'date-wise'}). Full breakdown is on the Data page.
            </Alert>
          </Grid>
        )}

        {carbonSavings && (
          <Grid item xs={12}>
            <DashboardSectionHeading
              title="Progress"
              subtitle="Summary of reduction progress — open Carbon savings for trends, achievements, and milestones."
            />
            <Card variant="outlined" sx={{ borderColor: alpha(theme.palette.primary.main, isDark ? 0.28 : 0.12) }}>
              <CardContent>
                <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }} sx={{ mb: 2 }}>
                  <Box sx={{ display: 'flex', alignItems: 'center', flex: 1 }}>
                    <EcoIcon color="primary" sx={{ mr: 1.5 }} />
                    <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>
                      {carbonSavings.totalSavings.toFixed(1)} kg CO₂ saved total ·{' '}
                      {carbonSavings.savingsPercentage.toFixed(1)}% reduction ·{' '}
                      {getPerformanceLabel(carbonSavings.benchmarkComparison.performance)}
                    </Typography>
                    {isLoadingSavings ? <CircularProgress size={20} sx={{ ml: 1 }} /> : null}
                  </Box>
                  <Button variant="outlined" size="small" onClick={() => navigate('/carbon-savings')}>
                    View carbon savings
                  </Button>
                </Stack>
                <Grid container spacing={2}>
                  <Grid item xs={6} sm={3}>
                    <Paper variant="outlined" sx={{ p: 1.5, textAlign: 'center' }}>
                      <Typography variant="h6">{carbonSavings.totalSavings.toFixed(1)}</Typography>
                      <Typography variant="caption" color="text.secondary">Total saved (kg)</Typography>
                    </Paper>
                  </Grid>
                  <Grid item xs={6} sm={3}>
                    <Paper variant="outlined" sx={{ p: 1.5, textAlign: 'center' }}>
                      <Typography variant="h6">{carbonSavings.periodSavings.toFixed(1)}</Typography>
                      <Typography variant="caption" color="text.secondary">This period (kg)</Typography>
                    </Paper>
                  </Grid>
                  <Grid item xs={6} sm={3}>
                    <Paper variant="outlined" sx={{ p: 1.5, textAlign: 'center' }}>
                      <Typography variant="h6">{carbonSavings.savingsPercentage.toFixed(1)}%</Typography>
                      <Typography variant="caption" color="text.secondary">Reduction</Typography>
                    </Paper>
                  </Grid>
                  <Grid item xs={6} sm={3}>
                    <Paper variant="outlined" sx={{ p: 1.5, textAlign: 'center' }}>
                      <Typography variant="h6">{carbonSavings.achievements?.length ?? 0}</Typography>
                      <Typography variant="caption" color="text.secondary">Achievements</Typography>
                    </Paper>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>
        )}

      </Grid>
    </Box>
  );
};

export default Dashboard;
