/**
 * Shared GHG scope palette and CO₂e disclosure copy for dashboards and reporting.
 * Scope 1: direct (warm). Scope 2: purchased energy (blue). Scope 3: value chain (slate).
 */
export const GHG_SCOPE_COLORS = {
  scope1: { fill: '#c2410c', stroke: '#7c2d12', label: 'Scope 1' },
  scope2: { fill: '#2563eb', stroke: '#1e3a8a', label: 'Scope 2' },
  scope3: { fill: '#475569', stroke: '#1e293b', label: 'Scope 3' },
} as const;

export const GHG_SCOPE_HEX = {
  scope1: GHG_SCOPE_COLORS.scope1.fill,
  scope2: GHG_SCOPE_COLORS.scope2.fill,
  scope3: GHG_SCOPE_COLORS.scope3.fill,
} as const;

/** Shown under chart titles for audit / disclosure alignment */
export const CO2E_METHODOLOGY_SUBTITLE =
  'Values are CO₂-equivalent (CO₂e), AR5 GWP-100, unless your inventory configuration overrides factors.';

export function formatCo2eFromKg(kg: number, options?: { maximumFractionDigits?: number }): string {
  const n = Number(kg);
  if (!Number.isFinite(n)) return '—';
  const abs = Math.abs(n);
  const digits = options?.maximumFractionDigits ?? (abs >= 1000 ? 2 : 1);
  if (abs >= 1000) {
    return `${(n / 1000).toLocaleString('en-IN', { maximumFractionDigits: digits })} t CO₂e`;
  }
  return `${n.toLocaleString('en-IN', { maximumFractionDigits: digits })} kg CO₂e`;
}

/** Y-axis caption when series are stored in kg CO₂e */
export function yAxisLabelForKgDomain(maxKg: number): string {
  if (!Number.isFinite(maxKg) || maxKg <= 0) return 'kg CO₂e';
  return maxKg >= 1000 ? 't CO₂e (1000 kg = 1 t)' : 'kg CO₂e';
}

export function formatAxisTickKg(value: number): string {
  if (!Number.isFinite(value)) return '';
  if (Math.abs(value) >= 1000) return `${(value / 1000).toFixed(1)}t`;
  return `${Math.round(value)}`;
}

const SCOPE1_KEYS = /scope\s*1|^s1$/i;
const SCOPE2_KEYS = /scope\s*2|^s2$/i;
const SCOPE3_KEYS = /scope\s*3|^s3$/i;

export function fillHexForScopeLabel(scopeLabel: string | undefined): string {
  const s = String(scopeLabel || '');
  if (SCOPE1_KEYS.test(s)) return GHG_SCOPE_HEX.scope1;
  if (SCOPE2_KEYS.test(s)) return GHG_SCOPE_HEX.scope2;
  if (SCOPE3_KEYS.test(s)) return GHG_SCOPE_HEX.scope3;
  return '#64748b';
}
