import React from 'react';
import { Navigate } from 'react-router-dom';
import { useRegistration } from '../context/RegistrationContext';

/** Sends legacy enterprise URLs to the MSME home experience. */
const EnterpriseRoutesRedirect: React.FC = () => {
  const { isRegistered } = useRegistration();
  return <Navigate to={isRegistered ? '/dashboard' : '/'} replace />;
};

export default EnterpriseRoutesRedirect;
