export interface NavSubPage {
  label: string;
  /** Route path; append `?tab=N` when the page uses tab query params. */
  path: string;
}

/** Disclosure report deep links grouped under Compliance in the workspace sidebar. */
function complianceReportingNavChildren(): NavSubPage[] {
  const children: NavSubPage[] = [
    { label: 'Reports overview', path: reportingTabHref('overview') },
    { label: 'BRSR report', path: reportingTabHref('brsr') },
    { label: 'ISO 14064 report', path: reportingTabHref('iso14064') },
  ];
  if (!HIDE_ISO_14067_UI) {
    children.push({ label: 'ISO 14067 report', path: reportingTabHref('iso14067') });
  }
  children.push({ label: 'CBAM report', path: reportingTabHref('cbam') });
  return children;
}

