/** Authenticated routes that render without the left navigation pane. */
export const ROUTES_WITHOUT_SIDEBAR = new Set([
  '/',
  '/login',
  '/register',
  '/forgot-password',
  '/privacy-policy',
  '/terms-of-service',
  '/pricing',
  '/about-us',
  '/enterprise/registration',
]);

export const isEnterpriseAppPath = (pathname: string): boolean =>
  pathname.startsWith('/enterprise');

/** Routes reachable before sign-in (header auth bypass). */
export const PUBLIC_ROUTES = new Set([...Array.from(ROUTES_WITHOUT_SIDEBAR), '/help', '/pricing']);

const OPERATIONS_ROUTE_PATHS = new Set(['/operations']);

export const ADMIN_ROUTE_PREFIX = '/admin';

export function isAdminRoute(pathname: string): boolean {
  return pathname.startsWith(ADMIN_ROUTE_PREFIX);
}

export function shouldShowAppSidebar(pathname: string, isRegistered: boolean): boolean {
  if (!isRegistered) {
    return false;
  }
  if (ROUTES_WITHOUT_SIDEBAR.has(pathname)) {
    return false;
  }
  if (isAdminRoute(pathname)) {
    return false;
  }
  return true;
}

export function parseNavPath(path: string): { pathname: string; tab: number | null } {
  const [pathname, search = ''] = path.split('?');
  const params = new URLSearchParams(search);
  const tabParam = params.get('tab');
  const tab = tabParam !== null && tabParam !== '' ? Number(tabParam) : null;
  return { pathname, tab: Number.isFinite(tab) ? tab : null };
}

export function isNavPathActive(currentPathname: string, currentSearch: string, navPath: string): boolean {
  const url = new URL(navPath, 'http://local');
  const navPathname = url.pathname;
  const navTab = url.searchParams.get('tab');
  const navSection = url.searchParams.get('section');
  const currentParams = new URLSearchParams(currentSearch);

  if (navPathname === '/operations' && OPERATIONS_ROUTE_PATHS.has(currentPathname)) {
    return true;
  }

  if (currentPathname !== navPathname) {
    return false;
  }

  if (navSection !== null) {
    if (navPathname === '/compliance/india' || navPathname === '/compliance/export') {
      return currentPathname === navPathname && currentParams.get('section') === navSection;
    }
    return currentParams.get('section') === navSection;
  }

  if (navTab !== null) {
    if (currentParams.has('section')) {
      return false;
    }
    const currentTab = currentParams.get('tab');
    if (navTab === '0' && (currentTab === null || currentTab === '')) {
      return true;
    }
    return currentTab === navTab;
  }

  if (currentParams.has('section') || currentParams.has('tab')) {
    return false;
  }

  return true;
}

export function isTopicActive(
  currentPathname: string,
  currentSearch: string,
  topic: NavTopic
): boolean {
  const { pathname: topicPathname } = parseNavPath(topic.path);
  if (
    topicPathname === '/msme-profile' &&
    OPERATIONS_ROUTE_PATHS.has(currentPathname) &&
    currentPathname !== '/msme-profile'
  ) {
    return true;
  }
  if (topicPathname === '/compliance') {
    if (
      currentPathname === '/compliance'
      || currentPathname.startsWith('/compliance/')
      || currentPathname === '/reporting'
    ) {
      return true;
    }
  }
  if (topicPathname === '/carbon-marketplace') {
    if (
      currentPathname === '/carbon-marketplace'
      || currentPathname.startsWith('/carbon-credits')
      || currentPathname.startsWith('/carbon-trading')
    ) {
      return true;
    }
  }
  if (topicPathname === '/data') {
    if (currentPathname === '/document-upload') {
      return true;
    }
  }
  if (currentPathname === topicPathname || currentPathname.startsWith(`${topicPathname}/`)) {
    return true;
  }
  return (
    topic.children?.some((child) => isNavPathActive(currentPathname, currentSearch, child.path)) ??
    false
  );
}
