import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Checkbox,
  CircularProgress,
  FormControl,
  FormControlLabel,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { reportingTabHref } from '../../constants/reportingTabs';
import ApiService from '../../services/api';
import {
  complianceWorkflowStatusLabel,
  INDIA_COMPLIANCE_SECTIONS,
  unwrapComplianceHubPayload,
} from '../../constants/complianceHub';
import { useUrlSectionParam } from '../../hooks/useUrlSectionParam';
import ComplianceTrackShell from './ComplianceTrackShell';
import ComplianceReadinessGrid from './ComplianceReadinessGrid';
import ComplianceJsonPanel from './ComplianceJsonPanel';
import { type IcmIntegrationConfig } from '../icm/IndianCarbonMarketPanel';

const SECTION_IDS = INDIA_COMPLIANCE_SECTIONS.map((s) => s.id);

const IndiaComplianceTrack: React.FC = () => {
  const [section, setSection] = useUrlSectionParam('overview', SECTION_IDS);
  const [period, setPeriod] = useState('annual');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [track, setTrack] = useState<Record<string, unknown> | null>(null);
  const [sbtiForm, setSbtiForm] = useState<Record<string, unknown>>({});
  const [saving, setSaving] = useState(false);
  const [newPlan, setNewPlan] = useState({
    title: '',
    scope: 'organization',
    targetReductionPercent: 10,
    dueDate: '',
  });

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getComplianceIndiaTrack({ period });
      const data = unwrapComplianceHubPayload<Record<string, unknown>>(res);
      setTrack(data);
      const sbti = (data?.modules as Record<string, unknown>)?.sbtiTargets;
      if (sbti && typeof sbti === 'object') {
        setSbtiForm(sbti as Record<string, unknown>);
      }
    } catch (e) {
      setTrack(null);
      setError(e instanceof Error ? e.message : 'Failed to load India compliance track');
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => {
    load();
  }, [load]);

  const modules = (track?.modules || {}) as Record<string, unknown>;
  const readiness = (track?.readiness || {}) as Record<string, string>;

  const saveSbti = async () => {
    setSaving(true);
    try {
      await ApiService.updateComplianceSbtiTargets(sbtiForm);
      await load();
    } finally {
      setSaving(false);
    }
  };

  const toggleAssuranceCheckpoint = async (checkpoints: { id: string; label: string; completed: boolean }[]) => {
    await ApiService.updateComplianceAssurance({ checkpoints });
    await load();
  };

  const addActionPlan = async () => {
    if (!newPlan.title.trim()) return;
    setSaving(true);
    try {
      await ApiService.createComplianceActionPlan(newPlan);
      setNewPlan({ title: '', scope: 'organization', targetReductionPercent: 10, dueDate: '' });
      await load();
    } finally {
      setSaving(false);
    }
  };

  const renderSection = () => {
    if (loading && !track) {
      return (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
          <CircularProgress />
        </Box>
      );
    }

    if (!track) {
      return null;
    }

    switch (section) {
      case 'overview':
        return (
          <ComplianceReadinessGrid
            items={[
              { key: 'brsr', label: 'BRSR Core', status: readiness.brsrCore },
              { key: 'iso', label: 'ISO assurance', status: readiness.isoAssurance },
              { key: 'pat', label: 'PAT intensity', status: readiness.patIntensity },
              { key: 'sbti', label: 'SBTi', status: readiness.sbti },
              { key: 'sync', label: 'Data sync', status: readiness.accountingSync },
            ]}
          />
        );
      case 'brsr-core':
        return (
          <ComplianceJsonPanel
            title="BRSR Core supplier pack (JSON)"
            data={modules.brsrCoreSupplierPack}
            filename="brsr-core-supplier-pack.json"
          />
        );
      case 'iso-assurance': {
        const assurance = modules.iso14064Assurance as Record<string, unknown>;
        const checkpoints = (assurance?.checkpoints || []) as {
          id: string;
          label: string;
          completed: boolean;
        }[];
        return (
          <Stack spacing={2}>
            <Alert severity="info">
              Overall readiness score:{' '}
              <strong>{Number(assurance?.overallReadinessScore || 0)}%</strong>. Complete checkpoints
              before limited assurance.
            </Alert>
            <Card variant="outlined">
              <CardContent>
                {checkpoints.map((cp) => (
                  <FormControlLabel
                    key={cp.id}
                    control={
                      <Checkbox
                        checked={cp.completed}
                        onChange={(e) => {
                          const next = checkpoints.map((c) =>
                            c.id === cp.id ? { ...c, completed: e.target.checked } : c
                          );
                          toggleAssuranceCheckpoint(next);
                        }}
                      />
                    }
                    label={cp.label}
                  />
                ))}
              </CardContent>
            </Card>
            <Button component={RouterLink} to={reportingTabHref('iso14064')} variant="outlined">
              Open ISO 14064 disclosure report
            </Button>
            <ComplianceJsonPanel
              title="ISO gap closure detail"
              data={assurance?.isoGapClosure}
              filename="iso-gap-closure.json"
            />
          </Stack>
        );
      }
      case 'pat-intensity': {
        const pat = modules.patEnergyIntensity as Record<string, unknown>;
        return (
          <Grid container spacing={2}>
            <Grid item xs={12} md={4}>
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="subtitle2" color="text.secondary">
                    Energy emissions
                  </Typography>
                  <Typography variant="h5">
                    {Number(pat?.energyEmissionsKgCo2e || 0).toLocaleString('en-IN')} kg
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} md={4}>
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="subtitle2" color="text.secondary">
                    Energy share of total
                  </Typography>
                  <Typography variant="h5">{Number(pat?.energySharePercent || 0)}%</Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} md={4}>
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="subtitle2" color="text.secondary">
                    Intensity / ₹ Cr turnover
                  </Typography>
                  <Typography variant="h5">
                    {pat?.intensityPerCrInrTurnover != null
                      ? Number(pat.intensityPerCrInrTurnover).toLocaleString('en-IN')
                      : '—'}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12}>
              <Typography variant="body2" color="text.secondary">
                {String(pat?.patRelevanceNote || '')}
              </Typography>
            </Grid>
          </Grid>
        );
      }
      case 'sbti-plans':
        return (
          <Stack spacing={3}>
            <Card variant="outlined">
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  SBTi-style targets
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={6} md={3}>
                    <TextField
                      label="Base year"
                      type="number"
                      fullWidth
                      value={sbtiForm.baseYear ?? ''}
                      onChange={(e) =>
                        setSbtiForm({ ...sbtiForm, baseYear: Number(e.target.value) })
                      }
                    />
                  </Grid>
                  <Grid item xs={6} md={3}>
                    <TextField
                      label="Near-term target year"
                      type="number"
                      fullWidth
                      value={sbtiForm.nearTermTargetYear ?? ''}
                      onChange={(e) =>
                        setSbtiForm({ ...sbtiForm, nearTermTargetYear: Number(e.target.value) })
                      }
                    />
                  </Grid>
                  <Grid item xs={6} md={3}>
                    <TextField
                      label="Reduction %"
                      type="number"
                      fullWidth
                      value={sbtiForm.nearTermReductionPercent ?? ''}
                      onChange={(e) =>
                        setSbtiForm({
                          ...sbtiForm,
                          nearTermReductionPercent: Number(e.target.value),
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={6} md={3}>
                    <FormControl fullWidth>
                      <InputLabel>Status</InputLabel>
                      <Select
                        label="Status"
                        value={sbtiForm.status || 'not_started'}
                        onChange={(e) => setSbtiForm({ ...sbtiForm, status: e.target.value })}
                      >
                        <MenuItem value="not_started">Not started</MenuItem>
                        <MenuItem value="committed">Committed</MenuItem>
                        <MenuItem value="targets_set">Targets set</MenuItem>
                        <MenuItem value="submitted">Submitted to SBTi</MenuItem>
                        <MenuItem value="validated">Validated</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>
                </Grid>
                <Button sx={{ mt: 2 }} variant="contained" onClick={saveSbti} disabled={saving}>
                  Save targets
                </Button>
              </CardContent>
            </Card>
            <Card variant="outlined">
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Reduction action plans
                </Typography>
                <Grid container spacing={2} sx={{ mb: 2 }}>
                  <Grid item xs={12} md={5}>
                    <TextField
                      label="Plan title"
                      fullWidth
                      value={newPlan.title}
                      onChange={(e) => setNewPlan({ ...newPlan, title: e.target.value })}
                    />
                  </Grid>
                  <Grid item xs={6} md={3}>
                    <TextField
                      label="Target reduction %"
                      type="number"
                      fullWidth
                      value={newPlan.targetReductionPercent}
                      onChange={(e) =>
                        setNewPlan({
                          ...newPlan,
                          targetReductionPercent: Number(e.target.value),
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={6} md={4}>
                    <Button variant="contained" onClick={addActionPlan} disabled={saving}>
                      Add plan
                    </Button>
                  </Grid>
                </Grid>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Title</TableCell>
                      <TableCell>Scope</TableCell>
                      <TableCell>Reduction %</TableCell>
                      <TableCell>Status</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {((modules.actionPlans as Record<string, unknown>[]) || []).map((plan) => (
                      <TableRow key={String(plan._id)}>
                        <TableCell>{String(plan.title)}</TableCell>
                        <TableCell>{String(plan.scope)}</TableCell>
                        <TableCell>{Number(plan.targetReductionPercent || 0)}%</TableCell>
                        <TableCell>{complianceWorkflowStatusLabel(String(plan.status))}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
                <Button
                  component={RouterLink}
                  to="/emissions-reduction-targets"
                  sx={{ mt: 2 }}
                  size="small"
                >
                  Open emissions targets dashboard
                </Button>
              </CardContent>
            </Card>
          </Stack>
        );
      case 'product-pcf':
        return (
          <Stack spacing={2}>
            <Alert severity="info">
              Register products for ISO 14067 PCF. Full PDF reports are under Disclosure reports.
            </Alert>
            <Button component={RouterLink} to={reportingTabHref('iso14067')} variant="contained">
              Generate ISO 14067 report
            </Button>
            <ComplianceJsonPanel
              title="Registered product footprints"
              data={modules.productFootprints}
              filename="product-footprints.json"
            />
          </Stack>
        );
      case 'carbon-market': {
        const icmPack = modules.indianCarbonMarket as IcmIntegrationConfig & Record<string, unknown>;
        const configured = (icmPack?.registryStatus as { configured?: boolean })?.configured;
        return (
          <Stack spacing={2}>
            <Alert severity={configured ? 'success' : 'info'}>
              Registry alignment and credit retirement are managed in the Carbon Marketplace. This section
              tracks compliance readiness only.
            </Alert>
            <ComplianceJsonPanel
              title="Indian carbon market alignment"
              data={modules.indianCarbonMarket}
              filename="indian-carbon-market.json"
            />
            <Button component={RouterLink} to="/carbon-marketplace" variant="contained">
              Open carbon marketplace
            </Button>
          </Stack>
        );
      }
      case 'data-sync': {
        const connectors = (modules.accountingSync || []) as Record<string, unknown>[];
        return (
          <Box>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Connector</TableCell>
                  <TableCell>Import</TableCell>
                  <TableCell>API sync</TableCell>
                  <TableCell>Status</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {connectors.map((c) => (
                  <TableRow key={String(c.id)}>
                    <TableCell>{String(c.name)}</TableCell>
                    <TableCell>{c.supportsImport ? 'Yes' : 'No'}</TableCell>
                    <TableCell>{c.supportsApiSync ? 'Yes' : 'No'}</TableCell>
                    <TableCell>{c.syncReady ? 'Ready' : String(c.recommendation)}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
            <Button component={RouterLink} to="/data?section=connectors" sx={{ mt: 2 }}>
              Configure data connectors
            </Button>
          </Box>
        );
      }
      default:
        return null;
    }
  };

  return (
    <ComplianceTrackShell
      trackTitle="India market compliance"
      trackDescription="Mandatory and market-driven requirements for Indian MSMEs: BRSR Core value chain, assurance, PAT-style intensity, SBTi, and domestic carbon markets."
      trackPath="/compliance/india"
      sections={INDIA_COMPLIANCE_SECTIONS}
      activeSection={section}
      onSectionChange={setSection}
      period={period}
      onPeriodChange={setPeriod}
      loading={loading}
    >
      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}
      {renderSection()}
    </ComplianceTrackShell>
  );
};

export default IndiaComplianceTrack;
