import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardActions,
  CardContent,
  CircularProgress,
  Grid,
  Typography,
} from '@mui/material';
import {
  ArrowForward as ArrowForwardIcon,
  Flag as IndiaIcon,
  Public as ExportIcon,
} from '@mui/icons-material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import ApiService from '../../services/api';
import { unwrapComplianceHubPayload } from '../../constants/complianceHub';
import ComplianceReadinessGrid from './ComplianceReadinessGrid';
import BuyerRequestInbox from './BuyerRequestInbox';

const ComplianceHubHome: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [overview, setOverview] = useState<Record<string, unknown> | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getComplianceHubOverview({ period: 'annual' });
      setOverview(unwrapComplianceHubPayload<Record<string, unknown>>(res));
    } catch (e) {
      setOverview(null);
      setError(e instanceof Error ? e.message : 'Failed to load compliance overview');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const indiaReadiness = (overview?.indiaReadiness || {}) as Record<string, string>;
  const exportReadiness = (overview?.exportReadiness || {}) as Record<string, string>;

  return (
    <Box>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 3, maxWidth: 720 }}>
        Structured workflows for the Indian market (BRSR Core, PAT, assurance, SBTi) and for global
        exporters (CBAM, CSRD, CDP, TCFD, EUDR, EcoVadis). Disclosure PDFs remain under{' '}
        <Button component={RouterLink} to="/reporting" size="small" sx={{ verticalAlign: 'baseline' }}>
          Disclosure reports
        </Button>
        .
      </Typography>

      {loading && (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
          <CircularProgress />
        </Box>
      )}
      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      {!loading && overview && (
        <>
          <Alert severity="info" sx={{ mb: 3 }}>
            {String(overview.companyName || 'Your company')} — total inventory{' '}
            <strong>{Number(overview.totalEmissionsKgCo2e || 0).toLocaleString('en-IN')} kg CO₂e</strong>{' '}
            (annual period).
          </Alert>

          <Typography variant="h6" sx={{ mb: 1 }}>
            India market readiness
          </Typography>
          <ComplianceReadinessGrid
            items={[
              { key: 'brsrCore', label: 'BRSR Core pack', status: indiaReadiness.brsrCore },
              { key: 'isoAssurance', label: 'ISO 14064 assurance', status: indiaReadiness.isoAssurance },
              { key: 'patIntensity', label: 'PAT / energy intensity', status: indiaReadiness.patIntensity },
              { key: 'sbti', label: 'SBTi targets', status: indiaReadiness.sbti },
              { key: 'accountingSync', label: 'Accounting sync', status: indiaReadiness.accountingSync },
            ]}
          />

          <Typography variant="h6" sx={{ mb: 1 }}>
            Global export readiness
          </Typography>
          <ComplianceReadinessGrid
            items={[
              { key: 'cbam', label: 'CBAM', status: exportReadiness.cbam },
              { key: 'productPcf', label: 'Product PCF', status: exportReadiness.productPcf },
              { key: 'csrd', label: 'CSRD supplier', status: exportReadiness.csrd },
              { key: 'cdp', label: 'CDP', status: exportReadiness.cdp },
              { key: 'tcfd', label: 'TCFD / ISSB', status: exportReadiness.tcfd },
              { key: 'supplierPortal', label: 'Buyer questionnaires', status: exportReadiness.supplierPortal },
              { key: 'eudr', label: 'EUDR', status: exportReadiness.eudr },
              { key: 'ecovadis', label: 'EcoVadis', status: exportReadiness.ecovadis },
            ]}
          />
        </>
      )}

      <Typography variant="h6" sx={{ mt: 3, mb: 1 }}>
        Buyer request inbox (AI)
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2, maxWidth: 720 }}>
        Open buyer audits and supplier questionnaires prioritized by due date and evidence readiness.
      </Typography>
      <BuyerRequestInbox />

      <Grid container spacing={3} sx={{ mt: 1 }}>
        <Grid item xs={12} md={6}>
          <Card variant="outlined" sx={{ height: '100%' }}>
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                <IndiaIcon color="primary" />
                <Typography variant="h6">India market track</Typography>
              </Box>
              <Typography variant="body2" color="text.secondary">
                BRSR Core supplier responses, ISO 14064 assurance workflow, PAT-style energy intensity,
                SBTi targets, product footprints, Indian carbon market, and accounting sync.
              </Typography>
            </CardContent>
            <CardActions>
              <Button
                endIcon={<ArrowForwardIcon />}
                onClick={() => navigate('/compliance/india')}
              >
                Open India track
              </Button>
            </CardActions>
          </Card>
        </Grid>
        <Grid item xs={12} md={6}>
          <Card variant="outlined" sx={{ height: '100%' }}>
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                <ExportIcon color="primary" />
                <Typography variant="h6">Global export track</Typography>
              </Box>
              <Typography variant="body2" color="text.secondary">
                CBAM, product PCF, CSRD supplier datapoints, CDP, TCFD/ISSB S2, buyer questionnaires,
                EUDR, and EcoVadis-aligned exports.
              </Typography>
            </CardContent>
            <CardActions>
              <Button
                endIcon={<ArrowForwardIcon />}
                onClick={() => navigate('/compliance/export')}
              >
                Open export track
              </Button>
            </CardActions>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
};

export default ComplianceHubHome;
