import React, { useCallback, useMemo, useState } from 'react';
import {
  AppBar,
  Avatar,
  Badge,
  Box,
  Button,
  Chip,
  Divider,
  FormControlLabel,
  IconButton,
  ListItemIcon,
  ListItemText,
  Menu,
  MenuItem,
  Stack,
  Switch,
  Toolbar,
  Tooltip,
  Typography,
} from '@mui/material';
import { useTheme } from '@mui/material/styles';
import {
  AccountCircle as AccountIcon,
  AdminPanelSettings as AdminIcon,
  Assessment as AssessmentIcon,
  Bolt as QuickActionsIcon,
  CloudOff as OfflineIcon,
  CloudDone as OnlineIcon,
  DarkMode as DarkModeIcon,
  ExpandLess as CollapseBannerIcon,
  ExpandMore as ExpandBannerIcon,
  HelpOutline as HelpIcon,
  LightMode as LightModeIcon,
  Logout as LogoutIcon,
  Notifications as NotificationsIcon,
  PersonAdd as RegisterIcon,
  PrivacyTip as PrivacyIcon,
  Settings as SettingsIcon,
  Summarize as ReportIcon,
  UploadFile as UploadIcon,
  GppGood as TermsIcon,
  InfoOutlined as AboutInfoIcon,
} from '@mui/icons-material';
import { Link as RouterLink, useLocation, useNavigate } from 'react-router-dom';
import { useRegistration } from '../context/RegistrationContext';
import { useThemeMode } from '../context/ThemeModeContext';
import PageInformationBanner from './PageInformationBanner';
import HeaderBreadcrumbs from './HeaderBreadcrumbs';
import BrandLockup from './BrandLockup';
import { PUBLIC_ROUTES, shouldShowAppSidebar } from '../constants/appNavigation';
import { headerMainColumnInsetSx } from '../constants/appShellLayout';
import { useHeaderWorkspace } from '../hooks/useHeaderWorkspace';
import { isAdminPortalUser, isAdminUserProfile, isViewRoleProfile } from '../utils/authRole';
const PAGE_BANNER_COLLAPSED_KEY = 'ci-page-banner-collapsed';

const routePathname = (path: string): string => path.split(/[?#]/)[0];

const QUICK_ACTIONS = [
  { label: 'Upload document', path: '/document-upload', icon: <UploadIcon fontSize="small" /> },
  { label: 'New assessment', path: '/carbon-footprint?section=start-assessment', icon: <AssessmentIcon fontSize="small" /> },
  { label: 'Generate report', path: '/reporting', icon: <ReportIcon fontSize="small" /> },
  { label: 'Help center', path: '/help', icon: <HelpIcon fontSize="small" /> },
] as const;

const readBannerCollapsed = (): boolean => {
  if (typeof window === 'undefined') {
    return false;
  }
  return window.localStorage.getItem(PAGE_BANNER_COLLAPSED_KEY) === 'true';
};

const Header: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const theme = useTheme();
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const [quickMenuAnchor, setQuickMenuAnchor] = useState<null | HTMLElement>(null);
  const [notificationsAnchor, setNotificationsAnchor] = useState<null | HTMLElement>(null);
  const [bannerCollapsed, setBannerCollapsed] = useState(readBannerCollapsed);
  const { isRegistered, hasCompletedRegistration, registrationData, logout } = useRegistration();
  const { isDarkMode, toggleThemeMode } = useThemeMode();
  const workspace = useHeaderWorkspace(isRegistered);
  const publicRoutes = useMemo(() => PUBLIC_ROUTES, []);
  const isAdmin = isAdminUserProfile();
  const isReviewer = isViewRoleProfile();
  const hasPortalAccess = isAdminPortalUser();
  const showBreadcrumbs = isRegistered && shouldShowAppSidebar(location.pathname, isRegistered);
  const isDevEnvironment = process.env.NODE_ENV === 'development';

  const handleMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleNavigation = useCallback(
    (path: string) => {
      if (!isRegistered && !publicRoutes.has(routePathname(path))) {
        navigate('/');
        handleMenuClose();
        setQuickMenuAnchor(null);
        setNotificationsAnchor(null);
        return;
      }

      navigate(path);
      handleMenuClose();
      setQuickMenuAnchor(null);
      setNotificationsAnchor(null);
    },
    [isRegistered, navigate, publicRoutes]
  );

  const handleAboutUsNavigation = useCallback(() => {
    handleNavigation('/about-us');
  }, [handleNavigation]);

  const handleAuthAction = () => {
    handleMenuClose();

    if (isRegistered) {
      logout();
      navigate('/');
      return;
    }

    navigate('/login?type=msme');
  };

  const toggleBannerCollapsed = () => {
    setBannerCollapsed((prev) => {
      const next = !prev;
      window.localStorage.setItem(PAGE_BANNER_COLLAPSED_KEY, String(next));
      return next;
    });
  };

  const carbonScoreColor = useMemo(() => {
    const score = workspace.carbonScore;
    if (score === null) {
      return 'default' as const;
    }
    if (score >= 80) {
      return 'success' as const;
    }
    if (score >= 50) {
      return 'warning' as const;
    }
    return 'error' as const;
  }, [workspace.carbonScore]);

  const mode = theme.palette.mode;
  const companyName = registrationData?.companyName?.trim();
  const industryLabel = registrationData?.industry?.trim();

  return (
    <AppBar
      position="sticky"
      elevation={0}
      color="inherit"
      sx={{
        bgcolor: 'background.paper',
        borderBottom: '1px solid',
        borderColor: 'divider',
        backdropFilter: 'blur(14px)',
        backgroundImage:
          mode === 'light'
            ? 'linear-gradient(180deg, rgba(255,255,255,0.92) 0%, rgba(255,255,255,0.78) 100%)'
            : 'linear-gradient(180deg, rgba(26,34,44,0.96) 0%, rgba(26,34,44,0.88) 100%)',
      }}
    >
      <Box
        component="a"
        href="#main-content"
        sx={{
          position: 'absolute',
          left: -9999,
          top: 'auto',
          width: 1,
          height: 1,
          overflow: 'hidden',
          '&:focus': {
            position: 'fixed',
            left: 16,
            top: 8,
            zIndex: theme.zIndex.tooltip + 1,
            width: 'auto',
            height: 'auto',
            overflow: 'visible',
            px: 2,
            py: 1,
            bgcolor: 'primary.main',
            color: 'primary.contrastText',
            borderRadius: 1,
            textDecoration: 'none',
            fontWeight: 600,
          },
        }}
      >
        Skip to main content
      </Box>

      <Toolbar sx={{ py: 1, minHeight: { xs: 68, md: 80, lg: 88 }, gap: 1, flexWrap: { xs: 'wrap', lg: 'nowrap' } }}>
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            cursor: 'pointer',
            mr: { xs: 0, sm: 'auto' },
            minWidth: 0,
            flex: { xs: '1 1 auto', sm: '0 1 auto' },
          }}
          onClick={() => handleNavigation(isRegistered ? '/dashboard' : '/')}
        >
          <BrandLockup
            variant="compact"
            logoWidth={{ xs: 48, sm: 56, md: 64 }}
            showTagline
            showVersion
            sx={{ mr: 0.5, flexShrink: 0 }}
          />
          {isDevEnvironment && (
            <Chip
              size="small"
              label="DEV"
              color="warning"
              sx={{ height: 20, alignSelf: 'center', display: { xs: 'none', md: 'inline-flex' } }}
            />
          )}
        </Box>

        {isRegistered && (
          <Stack
            direction="row"
            spacing={0.75}
            alignItems="center"
            useFlexGap
            sx={{
              order: { xs: 3, lg: 0 },
              width: { xs: '100%', lg: 'auto' },
              flex: { lg: 1 },
              minWidth: 0,
              justifyContent: { xs: 'flex-start', lg: 'center' },
              flexWrap: 'wrap',
            }}
          >
            {companyName && (
              <Tooltip title={companyName}>
                <Chip
                  size="small"
                  label={companyName}
                  variant="outlined"
                  sx={{
                    maxWidth: { xs: 160, sm: 220, md: 280 },
                    '& .MuiChip-label': { overflow: 'hidden', textOverflow: 'ellipsis' },
                  }}
                />
              </Tooltip>
            )}
            {industryLabel && (
              <Chip
                size="small"
                label={industryLabel}
                variant="outlined"
                color="default"
                sx={{ display: { xs: 'none', md: 'inline-flex' } }}
              />
            )}
            {workspace.setupIncomplete && (
              <Chip
                size="small"
                label="Setup incomplete"
                color="warning"
                clickable
                onClick={() => handleNavigation('/operations')}
                sx={{ display: { xs: 'none', sm: 'inline-flex' } }}
              />
            )}
            {workspace.carbonScore !== null && workspace.carbonScore > 0 && (
              <Tooltip title="Open dashboard for carbon score details">
                <Chip
                  size="small"
                  label={`Score ${workspace.carbonScore}`}
                  color={carbonScoreColor}
                  clickable
                  onClick={() => handleNavigation('/dashboard')}
                />
              </Tooltip>
            )}
            {workspace.totalTCO2e !== null && (
              <Chip
                size="small"
                label={`${workspace.totalTCO2e.toFixed(1)} tCO₂e`}
                variant="outlined"
                sx={{ display: { xs: 'none', lg: 'inline-flex' } }}
              />
            )}
            {workspace.apiOnline !== null && (
              <Tooltip
                title={
                  workspace.apiOnline
                    ? `Workspace connected${workspace.lastAssessmentLabel ? ` · Last assessment ${workspace.lastAssessmentLabel}` : ''}`
                    : 'Cannot reach API — data may be stale'
                }
              >
                <Chip
                  size="small"
                  icon={workspace.apiOnline ? <OnlineIcon /> : <OfflineIcon />}
                  label={workspace.apiOnline ? 'Live' : 'Offline'}
                  color={workspace.apiOnline ? 'success' : 'warning'}
                  variant="outlined"
                  sx={{ display: { xs: 'none', sm: 'inline-flex' } }}
                />
              </Tooltip>
            )}
          </Stack>
        )}

        {!isRegistered && (
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mr: 1, ml: 'auto' }}>
            <Button color="inherit" size="small" onClick={handleAboutUsNavigation}>
              About us
            </Button>
            <Button color="inherit" size="small" onClick={() => handleNavigation('/pricing')}>
              Pricing
            </Button>
            <Button
              color="primary"
              size="small"
              variant="text"
              component={RouterLink}
              to="/login?type=msme"
            >
              Login
            </Button>
            <Button
              color="primary"
              size="small"
              variant="outlined"
              component={RouterLink}
              to="/register?type=msme"
            >
              Register
            </Button>
          </Box>
        )}

        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            ml: isRegistered ? { xs: 'auto', lg: 0 } : 0,
          }}
        >
          {isRegistered && (
            <>
              <Tooltip title="Quick actions">
                <IconButton
                  aria-label="quick actions"
                  onClick={(event) => setQuickMenuAnchor(event.currentTarget)}
                  sx={{ color: 'text.primary' }}
                >
                  <QuickActionsIcon />
                </IconButton>
              </Tooltip>
              <Menu
                anchorEl={quickMenuAnchor}
                open={Boolean(quickMenuAnchor)}
                onClose={() => setQuickMenuAnchor(null)}
                transformOrigin={{ horizontal: 'right', vertical: 'top' }}
                anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
              >
                {QUICK_ACTIONS.map((action) => (
                  <MenuItem key={action.path} onClick={() => handleNavigation(action.path)}>
                    <ListItemIcon>{action.icon}</ListItemIcon>
                    <ListItemText>{action.label}</ListItemText>
                  </MenuItem>
                ))}
              </Menu>

              <Tooltip title="Notifications">
                <IconButton
                  aria-label="notifications"
                  onClick={(event) => setNotificationsAnchor(event.currentTarget)}
                  sx={{ color: 'text.primary' }}
                >
                  <Badge badgeContent={workspace.unreadCount} color="error" max={9}>
                    <NotificationsIcon />
                  </Badge>
                </IconButton>
              </Tooltip>
              <Menu
                anchorEl={notificationsAnchor}
                open={Boolean(notificationsAnchor)}
                onClose={() => setNotificationsAnchor(null)}
                PaperProps={{ sx: { minWidth: 320, maxWidth: 400 } }}
                transformOrigin={{ horizontal: 'right', vertical: 'top' }}
                anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
              >
                {workspace.notifications.length === 0 ? (
                  <MenuItem disabled>
                    <ListItemText primary="No new notifications" secondary="You're up to date." />
                  </MenuItem>
                ) : (
                  workspace.notifications.map((item) => (
                    <MenuItem
                      key={item.id}
                      onClick={() => {
                        handleNavigation(item.path);
                        workspace.dismissNotification(item.id);
                      }}
                    >
                      <ListItemText
                        primary={item.title}
                        secondary={item.description}
                        primaryTypographyProps={{ fontWeight: 600, fontSize: '0.875rem' }}
                        secondaryTypographyProps={{ fontSize: '0.75rem' }}
                      />
                    </MenuItem>
                  ))
                )}
              </Menu>
            </>
          )}

          <FormControlLabel
            sx={{
              mr: 1,
              ml: 0,
              color: 'text.secondary',
              display: { xs: 'none', sm: 'flex' },
            }}
            control={(
              <Switch
                checked={isDarkMode}
                onChange={toggleThemeMode}
                inputProps={{ 'aria-label': 'toggle dark mode' }}
                color="primary"
              />
            )}
            label={isDarkMode ? <DarkModeIcon fontSize="small" /> : <LightModeIcon fontSize="small" />}
            labelPlacement="start"
          />
          <IconButton
            size="large"
            aria-label="open user menu"
            onClick={handleMenuOpen}
            sx={{
              color: 'text.primary',
              '&:hover': {
                backgroundColor: mode === 'light' ? 'rgba(15, 23, 42, 0.06)' : 'rgba(255, 255, 255, 0.08)',
              },
            }}
          >
            <Avatar sx={{ width: 32, height: 32, bgcolor: 'primary.main', color: 'primary.contrastText' }}>
              <AccountIcon />
            </Avatar>
          </IconButton>

          <Menu
            anchorEl={anchorEl}
            open={Boolean(anchorEl)}
            onClose={handleMenuClose}
            PaperProps={{
              sx: {
                mt: 1,
                borderRadius: 2,
                minWidth: 240,
                boxShadow: '0 8px 32px rgba(0, 0, 0, 0.12)',
              },
            }}
            transformOrigin={{ horizontal: 'right', vertical: 'top' }}
            anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
          >
            {isRegistered && (companyName || registrationData?.email) && (
              <>
                <Box sx={{ px: 2, py: 1.25 }}>
                  {companyName && (
                    <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
                      {companyName}
                    </Typography>
                  )}
                  {registrationData?.email && (
                    <Typography variant="caption" color="text.secondary">
                      {registrationData.email}
                    </Typography>
                  )}
                </Box>
                <Divider />
              </>
            )}

            {isRegistered && (
              <MenuItem onClick={() => handleNavigation('/settings')}>
                <ListItemIcon>
                  <SettingsIcon fontSize="small" />
                </ListItemIcon>
                <ListItemText>Settings</ListItemText>
              </MenuItem>
            )}

            {isRegistered && hasPortalAccess && (
              <MenuItem onClick={() => handleNavigation('/admin/dashboard')}>
                <ListItemIcon>
                  <AdminIcon fontSize="small" />
                </ListItemIcon>
                <ListItemText>{isReviewer && !isAdmin ? 'Reviewer portal' : 'Admin portal'}</ListItemText>
              </MenuItem>
            )}

            {isRegistered && (
              <>
                <MenuItem onClick={handleAboutUsNavigation}>
                  <ListItemIcon>
                    <AboutInfoIcon fontSize="small" />
                  </ListItemIcon>
                  <ListItemText>About us</ListItemText>
                </MenuItem>
                <MenuItem onClick={() => handleNavigation('/help')}>
                  <ListItemIcon>
                    <HelpIcon fontSize="small" />
                  </ListItemIcon>
                  <ListItemText>Help center</ListItemText>
                </MenuItem>
              </>
            )}

            <MenuItem onClick={toggleThemeMode}>
              <ListItemIcon>
                {isDarkMode ? <DarkModeIcon fontSize="small" /> : <LightModeIcon fontSize="small" />}
              </ListItemIcon>
              <ListItemText>{isDarkMode ? 'Dark Mode' : 'Light Mode'}</ListItemText>
            </MenuItem>

            <Divider />

            {isRegistered && (
              <>
                <MenuItem onClick={() => handleNavigation('/data-privacy')}>
                  <ListItemIcon>
                    <PrivacyIcon fontSize="small" />
                  </ListItemIcon>
                  <ListItemText>Data privacy</ListItemText>
                </MenuItem>
                <MenuItem onClick={() => handleNavigation('/terms-of-service')}>
                  <ListItemIcon>
                    <TermsIcon fontSize="small" />
                  </ListItemIcon>
                  <ListItemText>Terms of service</ListItemText>
                </MenuItem>
                <Divider />
              </>
            )}

            {!isRegistered && (
              <>
                <MenuItem onClick={() => handleNavigation('/forgot-password')}>
                  <ListItemIcon>
                    <SettingsIcon fontSize="small" />
                  </ListItemIcon>
                  <ListItemText>Forgot Password</ListItemText>
                </MenuItem>
                <MenuItem onClick={() => handleNavigation('/register')}>
                  <ListItemIcon>
                    <RegisterIcon fontSize="small" />
                  </ListItemIcon>
                  <ListItemText>Create Account</ListItemText>
                </MenuItem>
                <Divider />
              </>
            )}

            <MenuItem onClick={handleAuthAction}>
              <ListItemIcon>
                <LogoutIcon fontSize="small" />
              </ListItemIcon>
              <ListItemText>
                {isRegistered ? 'Logout' : hasCompletedRegistration ? 'Login' : 'Back to Registration'}
              </ListItemText>
            </MenuItem>
          </Menu>
        </Box>
      </Toolbar>

      {showBreadcrumbs && (
        <Box sx={{ ...headerMainColumnInsetSx(showBreadcrumbs), pb: 0.5 }}>
          <HeaderBreadcrumbs />
        </Box>
      )}

      {isRegistered && (
        <Box sx={{ ...headerMainColumnInsetSx(showBreadcrumbs), pb: 1.25 }}>
          <Stack direction="row" alignItems="flex-start" spacing={1}>
            <Box sx={{ flex: 1, minWidth: 0 }}>
              {!bannerCollapsed && <PageInformationBanner />}
            </Box>
            <Tooltip title={bannerCollapsed ? 'Show page context' : 'Hide page context'}>
              <IconButton
                size="small"
                aria-label={bannerCollapsed ? 'expand page context banner' : 'collapse page context banner'}
                onClick={toggleBannerCollapsed}
                sx={{ mt: bannerCollapsed ? 0 : 0.5, flexShrink: 0 }}
              >
                {bannerCollapsed ? <ExpandBannerIcon fontSize="small" /> : <CollapseBannerIcon fontSize="small" />}
              </IconButton>
            </Tooltip>
          </Stack>
        </Box>
      )}
    </AppBar>
  );
};

export default Header;
